{
  "measure_id": "MEAS-D6FD5BF4",
  "restatements": [
    {
      "clause_id": "§1",
      "text": "Allows parents of children eligible for public school to open an education savings account, into which the state will deposit 90 percent of the per-pupil funding that would have gone to the child's resident public school district."
    },
    {
      "clause_id": "§2",
      "text": "Permits funds in the education savings account to be spent on private school tuition, tutoring, textbooks, and approved online courses."
    }
  ],
  "findings": [
    {
